 testCheck((bool)rows('SELECT f.id FROM facultades f JOIN grupos g ON g.facultad_id=f.id JOIN profesores p ON p.id=f.decano_id JOIN titulos t ON t.profesor_id=p.id JOIN telefonos_facultad tel ON tel.facultad_id=f.id WHERE f.id=? AND g.lider_id IS NOT NULL',[$created['facultad_id']]),'Alta compuesta cierra el ciclo facultad grupo profesor');
